import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Kimi Code 速查表","description":"只查不学。命令、flag、斜杠、模型 ID 和 Base URL 抄自官方文档。完整集合以 kimi --help 与 moonshotai.github.io/kimi-code 为准。","frontmatter":{"title":"Kimi Code 速查表","description":"只查不学。命令、flag、斜杠、模型 ID 和 Base URL 抄自官方文档。完整集合以 kimi --help 与 moonshotai.github.io/kimi-code 为准。","domain":"product","tags":["coding-agent"],"role":"cheatsheet"},"headers":[],"relativePath":"zh/products/kimi-code/kimi-code-cheatsheet.md","filePath":"zh/products/kimi-code/kimi-code-cheatsheet.md","lastUpdated":1787110548000}'),c={name:"zh/products/kimi-code/kimi-code-cheatsheet.md"};function i(a,t,l,h,n,s){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="kimi-code-速查表" tabindex="-1">Kimi Code 速查表 <a class="header-anchor" href="#kimi-code-速查表" aria-label="Permalink to &quot;Kimi Code 速查表&quot;">​</a></h1><p>只查不学。CLI 以 <a href="https://moonshotai.github.io/kimi-code/zh/reference/kimi-command" target="_blank" rel="noreferrer">kimi 命令</a> 和 <code>kimi --help</code> 为准。模型 / 会员以 <a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">models</a> 和 <a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">membership</a> 为准。</p><p>覆盖 2026-08-19 打开的官方页。npm <code>@moonshot-ai/kimi-code</code> 当日 <code>latest</code> 为 <code>0.37.1</code>。先跑 <code>kimi --version</code> 再对 <a href="https://moonshotai.github.io/kimi-code/zh/release-notes/changelog" target="_blank" rel="noreferrer">changelog</a>。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>命令</th></tr></thead><tbody><tr><td>macOS / Linux（推荐）</td><td><code>curl -fsSL https://code.kimi.com/kimi-code/install.sh | bash</code></td></tr><tr><td>Windows PowerShell</td><td><code>irm https://code.kimi.com/kimi-code/install.ps1 | iex</code></td></tr><tr><td>npm（Node <strong>≥ 22.19.0</strong>）</td><td><code>npm install -g @moonshot-ai/kimi-code</code></td></tr><tr><td>pnpm</td><td><code>pnpm add -g @moonshot-ai/kimi-code</code></td></tr><tr><td>看版本</td><td><code>kimi --version</code>（<code>-V</code>）</td></tr><tr><td>升级</td><td><code>kimi upgrade</code>（别名 <code>kimi update</code>）</td></tr><tr><td>npm 升级</td><td><code>npm install -g @moonshot-ai/kimi-code@latest</code></td></tr><tr><td>Homebrew 升级</td><td><code>brew upgrade kimi-code</code>（What&#39;s New；Getting Started 无 install 原文）</td></tr><tr><td>npm 卸载</td><td><code>npm uninstall -g @moonshot-ai/kimi-code</code></td></tr></tbody></table><p>Windows 先装 Git for Windows；非标准路径设 <code>KIMI_SHELL_PATH</code> 为 <code>bash.exe</code> 绝对路径。</p><p>旧脚本 <code>https://code.kimi.com/install.sh</code>（无 <code>kimi-code/</code>）和 <code>uv tool install … kimi-cli</code> 是 Python 旧线，不要用。</p><h2 id="主命令-flag" tabindex="-1">主命令 flag <a class="header-anchor" href="#主命令-flag" aria-label="Permalink to &quot;主命令 flag&quot;">​</a></h2><p>来源：<a href="https://moonshotai.github.io/kimi-code/zh/reference/kimi-command" target="_blank" rel="noreferrer">kimi 命令</a></p><table tabindex="0"><thead><tr><th>选项</th><th>短</th><th>说明</th></tr></thead><tbody><tr><td><code>--version</code></td><td><code>-V</code></td><td>打印版本</td></tr><tr><td><code>--help</code></td><td><code>-h</code></td><td>帮助</td></tr><tr><td><code>--session [id]</code></td><td><code>-S</code></td><td>恢复会话；无 ID 则交互选择。隐藏别名 <code>-r</code> / <code>--resume</code></td></tr><tr><td><code>--continue</code></td><td><code>-c</code></td><td>继续当前目录最近会话</td></tr><tr><td><code>--model &lt;model&gt;</code></td><td><code>-m</code></td><td>本次模型别名</td></tr><tr><td><code>--prompt &lt;prompt&gt;</code></td><td><code>-p</code></td><td>非交互单次 prompt，无 TUI</td></tr><tr><td><code>--output-format &lt;format&gt;</code></td><td></td><td><code>text</code> 或 <code>stream-json</code>，只能配 <code>-p</code></td></tr><tr><td><code>--yolo</code></td><td><code>-y</code></td><td>自动批准普通工具。隐藏别名 <code>--yes</code>、<code>--auto-approve</code></td></tr><tr><td><code>--auto</code></td><td></td><td>auto 权限，不再提问</td></tr><tr><td><code>--plan</code></td><td></td><td>以 Plan 模式开新会话</td></tr><tr><td><code>--skills-dir &lt;dir&gt;</code></td><td></td><td>替换自动发现的 Skills 目录，可重复</td></tr><tr><td><code>--agent &lt;name&gt;</code></td><td></td><td>指定 main agent（不可与 <code>--session</code>/<code>--continue</code> 同用）</td></tr><tr><td><code>--agent-file &lt;path&gt;</code></td><td></td><td>从 Markdown 加载 Agent</td></tr><tr><td><code>--add-dir &lt;dir&gt;</code></td><td></td><td>追加工作目录，可重复</td></tr></tbody></table><p>互斥：<code>--continue</code> × <code>--session</code>；<code>--yolo</code> × <code>--auto</code>；<code>-p</code> 不能配 <code>--yolo</code> / <code>--auto</code> / <code>--plan</code>。<code>-p</code> 固定 <code>auto</code> 权限。</p><h2 id="子命令" tabindex="-1">子命令 <a class="header-anchor" href="#子命令" aria-label="Permalink to &quot;子命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>kimi</code></td><td>无参数：当前目录新 TUI 会话</td></tr><tr><td><code>kimi login</code></td><td>非交互 OAuth device-code</td></tr><tr><td><code>kimi acp</code></td><td>ACP stdio，给 IDE</td></tr><tr><td><code>kimi web</code></td><td>前台 REST/WS + web UI。默认端口 <code>58627</code></td></tr><tr><td><code>kimi doctor</code></td><td>校验 <code>config.toml</code> / <code>tui.toml</code></td></tr><tr><td><code>kimi export [sessionId]</code></td><td>打包会话 ZIP</td></tr><tr><td><code>kimi migrate</code></td><td>从旧 <code>kimi-cli</code> 迁数据</td></tr><tr><td><code>kimi upgrade</code></td><td>检查并安装更新</td></tr><tr><td><code>kimi vis [sessionId]</code></td><td>浏览器里可视化会话</td></tr><tr><td><code>kimi provider …</code></td><td>非交互管理供应商</td></tr></tbody></table><p><code>kimi server …</code> 已废弃（退出码 1），改用 <code>kimi web</code>。例外：<code>kimi server kill</code> 只停 0.28.0 之前的后台服务。</p><h2 id="斜杠命令-入门子集" tabindex="-1">斜杠命令（入门子集） <a class="header-anchor" href="#斜杠命令-入门子集" aria-label="Permalink to &quot;斜杠命令（入门子集）&quot;">​</a></h2><p>全集：<a href="https://moonshotai.github.io/kimi-code/zh/reference/slash-commands" target="_blank" rel="noreferrer">slash-commands</a></p><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>作用</th></tr></thead><tbody><tr><td><code>/login</code></td><td></td><td>OAuth 或 Platform Key</td></tr><tr><td><code>/logout</code></td><td></td><td>清当前凭证</td></tr><tr><td><code>/model</code></td><td></td><td>切换模型</td></tr><tr><td><code>/provider</code></td><td></td><td>供应商管理器</td></tr><tr><td><code>/new</code></td><td><code>/clear</code></td><td>新会话</td></tr><tr><td><code>/sessions</code></td><td><code>/resume</code></td><td>恢复历史</td></tr><tr><td><code>/fork</code></td><td></td><td>派生副本</td></tr><tr><td><code>/compact [指令]</code></td><td></td><td>压缩上下文</td></tr><tr><td><code>/init</code></td><td></td><td>生成 <code>AGENTS.md</code></td></tr><tr><td><code>/usage</code></td><td></td><td>用量 / 配额</td></tr><tr><td><code>/status</code></td><td></td><td>运行时状态</td></tr><tr><td><code>/yolo [on|off]</code></td><td><code>/yes</code></td><td>YOLO</td></tr><tr><td><code>/auto [on|off]</code></td><td></td><td>Auto</td></tr><tr><td><code>/plan [on|off]</code></td><td></td><td>Plan</td></tr><tr><td><code>/goal …</code></td><td></td><td>目标模式</td></tr><tr><td><code>/swarm &lt;task&gt;</code></td><td></td><td>多 Agent 并行</td></tr><tr><td><code>/btw [问题]</code></td><td></td><td>旁路 subagent</td></tr><tr><td><code>/mcp</code></td><td></td><td>MCP 状态</td></tr><tr><td><code>/mcp-config</code></td><td></td><td>配置 MCP（内置 Skill）</td></tr><tr><td><code>/help</code></td><td><code>/h</code> <code>/?</code></td><td>帮助</td></tr><tr><td><code>/exit</code></td><td><code>/quit</code> <code>/q</code></td><td>退出</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>作用</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>发送</td></tr><tr><td><code>Shift-Enter</code> / <code>Ctrl-J</code></td><td>换行</td></tr><tr><td><code>Esc</code></td><td>中断 / 关弹窗</td></tr><tr><td><code>Ctrl-C</code></td><td>中断；空闲连按两次退出</td></tr><tr><td><code>Ctrl-D</code></td><td>输入框为空时退出</td></tr><tr><td><code>Shift-Tab</code></td><td>切 Plan</td></tr><tr><td><code>Ctrl-S</code></td><td>流式中插话</td></tr><tr><td><code>Ctrl-O</code></td><td>折叠工具输出</td></tr><tr><td><code>Ctrl-G</code></td><td>外部编辑器</td></tr><tr><td><code>!</code>（空输入框）</td><td>Shell 模式</td></tr><tr><td><code>@</code></td><td>文件引用</td></tr><tr><td><code>/</code></td><td>斜杠命令</td></tr></tbody></table><p>粘贴媒体：macOS/Linux <code>Ctrl-V</code>，Windows <code>Alt-V</code>。</p><h2 id="vs-code-扩展" tabindex="-1">VS Code 扩展 <a class="header-anchor" href="#vs-code-扩展" aria-label="Permalink to &quot;VS Code 扩展&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Marketplace</td><td><a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">moonshot-ai.kimi-code</a></td></tr><tr><td>搜</td><td><code>Kimi Code</code>，发布者 <code>moonshot-ai</code></td></tr><tr><td>资格</td><td>产品文档：新装仅旧版 Python CLI 用户</td></tr><tr><td>VS Code 版本（Marketplace）</td><td><code>&gt;= 1.100.0</code></td></tr><tr><td>聚焦输入</td><td><code>Ctrl+Shift+K</code> / <code>Cmd+Shift+K</code></td></tr><tr><td>插入当前文件</td><td><code>Alt+K</code></td></tr><tr><td>新对话</td><td><code>Ctrl+N</code> / <code>Cmd+N</code>（需 <code>kimi.enableNewConversationShortcut</code>）</td></tr></tbody></table><h2 id="模型-id" tabindex="-1">模型 ID <a class="header-anchor" href="#模型-id" aria-label="Permalink to &quot;模型 ID&quot;">​</a></h2><p>来源：<a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">模型配置</a>（3 个 ID）</p><table tabindex="0"><thead><tr><th>Model ID</th><th>模型</th><th>上下文</th><th>档位</th></tr></thead><tbody><tr><td><code>k3</code></td><td>Kimi K3</td><td>Moderato 256k；Allegretto+ 最高 1M</td><td>Moderato+（Andante 暂不支持）</td></tr><tr><td><code>kimi-for-coding</code></td><td>K2.7 Code</td><td>256k</td><td>全部会员</td></tr><tr><td><code>kimi-for-coding-highspeed</code></td><td>同上，高速</td><td>256k</td><td>Allegretto+</td></tr></tbody></table><p>高速版填错会静默落到标准版。越权 → <code>401</code>。第三方用满 1M 时把上下文窗口写成 <code>1048576</code>。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Kimi Code</th><th>开放平台</th></tr></thead><tbody><tr><td>OpenAI Base URL</td><td><code>https://api.kimi.com/coding/v1</code></td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>Anthropic Base URL</td><td><code>https://api.kimi.com/coding/</code></td><td>—</td></tr><tr><td>计费</td><td>会员 + 频控</td><td>按量</td></tr><tr><td>建 Key</td><td><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">控制台</a>（最多 5 个，只显示一次）</td><td>开放平台控制台</td></tr></tbody></table><p>Key 不通用。不要改 User-Agent。</p><h2 id="路径与环境变量" tabindex="-1">路径与环境变量 <a class="header-anchor" href="#路径与环境变量" aria-label="Permalink to &quot;路径与环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键 / 路径</th><th>作用</th></tr></thead><tbody><tr><td><code>~/.kimi-code/</code></td><td>现行数据根</td></tr><tr><td><code>~/.kimi-code/config.toml</code></td><td>Agent / 权限 / provider</td></tr><tr><td><code>~/.kimi-code/tui.toml</code></td><td>主题、编辑器、通知、自动更新</td></tr><tr><td><code>~/.kimi/</code></td><td><strong>旧</strong> Python CLI，不要手混</td></tr><tr><td><code>KIMI_CODE_HOME</code></td><td>覆盖数据根</td></tr><tr><td><code>KIMI_SHELL_PATH</code></td><td>Windows 上 <code>bash.exe</code></td></tr><tr><td><code>KIMI_DISABLE_TELEMETRY=1</code></td><td>关匿名遥测（也接受 <code>true</code>/<code>yes</code>/<code>y</code>）</td></tr></tbody></table><p><code>KIMI_API_KEY</code> <strong>不</strong>从 shell 读取。</p><h2 id="权限模式对照" tabindex="-1">权限模式对照 <a class="header-anchor" href="#权限模式对照" aria-label="Permalink to &quot;权限模式对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>CLI</th><th>TUI</th><th>行为</th></tr></thead><tbody><tr><td>默认 manual</td><td>（不加 flag）</td><td></td><td>写文件 / Shell 先问</td></tr><tr><td>Plan</td><td><code>--plan</code></td><td><code>Shift-Tab</code> <code>/plan</code></td><td>先方案；退出仍要批（YOLO 也跳不过）</td></tr><tr><td>YOLO</td><td><code>--yolo</code> <code>-y</code></td><td><code>/yolo</code></td><td>普通工具自动批</td></tr><tr><td>Auto</td><td><code>--auto</code></td><td><code>/auto</code></td><td>全自动且不问用户</td></tr><tr><td><code>-p</code></td><td>固定 auto</td><td>—</td><td>不能再叠 yolo/auto/plan</td></tr></tbody></table><h2 id="高质量信息源" tabindex="-1">高质量信息源 <a class="header-anchor" href="#高质量信息源" aria-label="Permalink to &quot;高质量信息源&quot;">​</a></h2><ul><li><strong><a href="https://www.kimi.com/code" target="_blank" rel="noreferrer">Kimi Code 产品页</a></strong> — 落地页与现行 curl 安装栏 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">产品文档总览</a></strong> — 会员权益、VS Code、API、模型入口 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://moonshotai.github.io/kimi-code/zh/" target="_blank" rel="noreferrer">CLI 文档站（中）</a></strong> / <strong><a href="https://moonshotai.github.io/kimi-code/en/" target="_blank" rel="noreferrer">EN</a></strong> — Guides + Reference <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">模型配置</a></strong> — 3 个 Model ID 与档位 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">会员权益</a></strong> — 7 天 / 5 小时、加油包 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New</a></strong> — CLI 重写对照、功能发布 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">产品对照</a></strong> — Kimi / Work / Code / Claw <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">GitHub MoonshotAI/kimi-code</a></strong> — README、源码、Issues <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.npmjs.com/package/@moonshot-ai/kimi-code" target="_blank" rel="noreferrer">npm @moonshot-ai/kimi-code</a></strong> — 版本与 <code>engines</code><ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">VS Marketplace moonshot-ai.kimi-code</a></strong> — 扩展实现说明 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">控制台</a></strong> — Key 与额度 <ul><li>最后核实：2026-08-19</li></ul></li><li><strong><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">开放平台</a></strong> — 按量 API，不是 Code 会员池 <ul><li>最后核实：2026-08-19</li></ul></li></ul><h3 id="待核实" tabindex="-1">待核实 <a class="header-anchor" href="#待核实" aria-label="Permalink to &quot;待核实&quot;">​</a></h3><ul><li>产品总览是否仍展示第四个模型 ID <code>k3-256k</code>（2026-08-19 与 models 页不一致）</li><li><code>brew install</code> 的官方原文（目前只有 <code>brew upgrade kimi-code</code>）</li><li>Kimi Claw 独立落地 URL（对照页有产品名，无单独域名）</li></ul>',38)])])}const g=d(c,[["render",i]]);export{u as __pageData,g as default};
